Given an integer n. The task is to find the first n Fibonacci Numbers.Examples : Input: n = 3Output: 0 1 1Input: n = 7Output: 0 1 1 2 3 5 8Try It YourselfRecursive Approach -  O(n*2n) Time and O(n) SpaceFind nth fibonacci number by calling for n-1 and n-2 and adding their return value. The base case will be if n=0 or n=1 then the fibonacci number will be 0 and 1 respectively.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int findFibonacci(int n) {

   // base case n = 0  n = 1
   if (n == 0) {
      return 0;
   } else if (n == 1) {
      return 1;
   } else {
      return findFibonacci(n - 2) + findFibonacci(n - 1);
   }
}

vector<int> fibonacciNumbers(int n) {
   vector<int> ans;
   for (int i = 0; i < n; i++) {
      ans.push_back(findFibonacci(i));
   }
   return ans;
}

int main() {
   int n = 7;
   vector<int> res = fibonacciNumbers(n);
   for (int i = 0; i < res.size(); i++) {
      cout << res[i] << " ";
   }
   return 0;
}


