            C++

    #include <bits/stdc++.h>
using namespace std;

vector<int> fibonacciNumbers(int n) {
   vector<int> ans;
   int f1 = 0, f2 = 1, i;
   ans.push_back(f1);

   for (i = 1; i < n; i++) {
      ans.push_back(f2);
      int next = f1 + f2;
      f1 = f2;
      f2 = next;
   }
   return ans;
}

int main() {
   int n = 7;
   vector<int> res = fibonacciNumbers(n);
   for (int i = 0; i < res.size(); i++) {
      cout << res[i] << " ";
   }
   return 0;
}


